//! Wolfram transfer-conservation replay for PC fan CFD state transfer.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `wolfram/transfer_golden.wls` under Wolfram Engine 15.0.0) carries the
//! exact volumes of a reference tetrahedron (1/6) and its half-scale nested
//! tet (1/48), per audit-sonium-sim-pcfan-20260921 (conservation and
//! transfer-adjoint behavior on small production meshes). The replay drives
//! the production `transfer_pc_fan_cfd_state` path: a constant state moved
//! between equal-measure meshes is exact with a vanishing conservative
//! correction, while the nested unequal-measure transfer must fail closed
//! reporting Wolfram's two volumes as the mismatch measures.

use serde::Deserialize;
use sonium_fem::mesh::{ElementType, InterpolationError, Mesh, Point};
use sonium_sim_pcfan::{PcFanCfdStateTransferError, transfer_pc_fan_cfd_state};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Volume {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    source_volume: Volume,
    target_volume: Volume,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram transfer fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    assert_eq!(fixture.source_volume.exact, "1/6");
    assert_eq!(fixture.target_volume.exact, "1/48");
    fixture
}

/// One positively oriented reference tet, optionally half-scaled and with
/// an even node permutation (two swaps preserve orientation).
fn reference_tet(scale: f64, permute: bool) -> Mesh {
    let mut mesh = Mesh::new(3);
    let corners = [
        [0.0, 0.0, 0.0],
        [scale, 0.0, 0.0],
        [0.0, scale, 0.0],
        [0.0, 0.0, scale],
    ];
    let order = if permute { [1, 0, 3, 2] } else { [0, 1, 2, 3] };
    let nodes: Vec<usize> = order
        .iter()
        .map(|index| {
            mesh.add_node(Point {
                x: corners[*index][0],
                y: corners[*index][1],
                z: corners[*index][2],
            })
        })
        .collect();
    mesh.add_element(ElementType::Tetrahedron, nodes);
    mesh
}

const VELOCITY: [f64; 3] = [1.5, -2.0, 0.5];
const PRESSURE_PA: f64 = 101_325.0;

#[test]
fn constant_state_transfer_matches_wolfram_volume() {
    let fixture = parse_fixture();
    let source = reference_tet(1.0, false);
    // Same geometry with renumbered nodes: exercises validation, the
    // locator, and both interpolations without changing the measure.
    let target = reference_tet(1.0, true);
    let source_velocity = vec![VELOCITY; source.nodes.len()];
    let source_pressure = vec![PRESSURE_PA; source.nodes.len()];

    let transfer = transfer_pc_fan_cfd_state(&source, &target, &source_velocity, &source_pressure)
        .expect("equal-measure transfer succeeds");

    // Wolfram's independent volume pins the report geometry on both sides.
    let expected = parse(&fixture.source_volume.value);
    assert!(
        (transfer.report.source_volume_m3 - expected).abs() <= 1e-15,
        "source volume {} != Wolfram {expected:e}",
        transfer.report.source_volume_m3
    );
    assert!(
        (transfer.report.target_volume_m3 - expected).abs() <= 1e-15,
        "target volume {} != Wolfram {expected:e}",
        transfer.report.target_volume_m3
    );

    // Constant fields are exactly representable: interpolation is exact
    // and the conservative correction must vanish.
    assert!(
        transfer.report.max_velocity_correction_m_s <= 1e-9,
        "constant velocity needed no correction: {}",
        transfer.report.max_velocity_correction_m_s
    );
    assert!(
        transfer.report.max_pressure_correction_pa <= 1e-9,
        "constant pressure needed no correction: {}",
        transfer.report.max_pressure_correction_pa
    );
    for (node, velocity) in transfer.velocity_m_s.iter().enumerate() {
        for (component, (got, want)) in velocity.iter().zip(VELOCITY.iter()).enumerate() {
            assert!(
                (got - want).abs() <= 1e-9,
                "node {node} component {component}: {got:e} != {want:e}"
            );
        }
    }
    for (node, got) in transfer.pressure_pa.iter().enumerate() {
        assert!(
            (got - PRESSURE_PA).abs() <= 1e-9,
            "node {node} pressure {got:e} != {PRESSURE_PA:e}"
        );
    }
}

#[test]
fn unequal_measure_transfer_fails_closed_with_wolfram_measures() {
    let fixture = parse_fixture();
    let source = reference_tet(1.0, false);
    let nested = reference_tet(0.5, false);
    // A conservative transfer cannot preserve both pointwise values and
    // integrals across different measures: it must fail closed rather
    // than silently rescale the state.
    let result = transfer_pc_fan_cfd_state(
        &source,
        &nested,
        &vec![VELOCITY; source.nodes.len()],
        &vec![PRESSURE_PA; source.nodes.len()],
    );
    match result {
        Err(PcFanCfdStateTransferError::Interpolation(
            InterpolationError::ConservationMismatch {
                source_measure,
                target_measure,
            },
        )) => {
            let expected_source = parse(&fixture.source_volume.value);
            let expected_target = parse(&fixture.target_volume.value);
            assert!(
                (source_measure - expected_source).abs() <= 1e-15,
                "mismatch source {source_measure:e} != Wolfram {expected_source:e}"
            );
            assert!(
                (target_measure - expected_target).abs() <= 1e-15,
                "mismatch target {target_measure:e} != Wolfram {expected_target:e}"
            );
        }
        other => panic!("nested transfer must fail closed, got {other:?}"),
    }
}
